    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#fde68a;">Indirect question</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">A question inside a polite frame, e.g. “Could you tell me…?”</td>
    </tr>
